// Tests of the gen and vectors --kind commands (docs/plans/status-v1.md, C-5): run('gen') refuses an unknown kind, and the
// command line writes the generated set under --out, removes the stale generated files there, and refuses a file without the
// status-gen header (it is reported as a finding; nothing is written or removed). Every case writes into a temporary
// directory that is removed when the file's tests end.
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import test, { after } from 'node:test';
import { fileURLToPath } from 'node:url';
import { run } from '../src/core/run.mjs';
import { jsonStore } from '../src/store-json/store.mjs';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(HERE, '../../..');
const CLI = path.resolve(HERE, '../src/cli/status-gen.mjs');
const GOLDEN = path.join(HERE, 'golden/npm');
const roots = [];

/** A new temporary directory, removed when the file's tests end. */
function tempDir() {
  const root = mkdtempSync(path.join(tmpdir(), 'status-gen-npm-'));
  roots.push(root);
  return root;
}

/** Runs the command line of status-gen with `args` and returns its status, stdout and stderr. */
function gen(args) {
  const result = spawnSync(process.execPath, [CLI, ...args], { encoding: 'utf8' });
  return { status: result.status, stdout: result.stdout, stderr: result.stderr };
}

const golden = name => readFileSync(path.join(GOLDEN, name), 'utf8');
const GOLDEN_SRC = ['order.js', 'order.d.ts', 'status.js', 'status.d.ts', 'index.js', 'index.d.ts'];

after(() => {
  for (const root of roots) rmSync(root, { recursive: true, force: true });
});

test('run gen refuses an unknown kind with an Error and reads nothing', async () => {
  await assert.rejects(run('gen', jsonStore(ROOT), { kind: 'ruby' }), /unknown kind ruby/);
  await assert.rejects(run('gen', jsonStore(ROOT), {}), /unknown kind undefined/);
});

test('gen --kind npm writes the golden src files and exits 0 with a one-line summary', () => {
  const out = path.join(tempDir(), 'src');
  assert.deepEqual(gen(['gen', '--project', ROOT, '--kind', 'npm', '--out', out]), { status: 0, stdout: '[status-gen] gen: ok\n', stderr: '' });
  for (const name of GOLDEN_SRC) assert.equal(readFileSync(path.join(out, name), 'utf8'), golden(`src/${name}`), name);
});

test('gen removes a stale file that carries the generated header and keeps the others', () => {
  const out = path.join(tempDir(), 'src');
  mkdirSync(out, { recursive: true });
  writeFileSync(path.join(out, 'stale.js'), '// Code generated by status-gen from gone; DO NOT EDIT.\nexport {};\n');
  assert.equal(gen(['gen', '--project', ROOT, '--kind', 'npm', '--out', out]).status, 0);
  assert.equal(existsSync(path.join(out, 'stale.js')), false);
  assert.equal(readFileSync(path.join(out, 'order.js'), 'utf8'), golden('src/order.js'));
});

test('gen refuses a file without the header: a finding, exit 1, and nothing written or removed', () => {
  const out = path.join(tempDir(), 'src');
  mkdirSync(out, { recursive: true });
  writeFileSync(path.join(out, 'order.js'), 'export const hand = 1;\n');
  writeFileSync(path.join(out, 'notes.txt'), 'hand written\n');
  const result = gen(['gen', '--project', ROOT, '--kind', 'npm', '--out', out]);
  assert.equal(result.status, 1);
  assert.match(result.stderr, /^\[status-gen\] E_NOT_GENERATED - order\.js: /m);
  assert.match(result.stderr, /^\[status-gen\] E_NOT_GENERATED - notes\.txt: /m);
  assert.equal(readFileSync(path.join(out, 'order.js'), 'utf8'), 'export const hand = 1;\n');
  assert.equal(existsSync(path.join(out, 'status.js')), false);
  assert.equal(existsSync(path.join(out, 'notes.txt')), true);
});

test('gen with an unknown kind, or without --kind, is a usage error with exit 2 and writes nothing', () => {
  const out = path.join(tempDir(), 'src');
  const unknown = gen(['gen', '--project', ROOT, '--kind', 'ruby', '--out', out]);
  assert.equal(unknown.status, 2);
  assert.match(unknown.stderr, /usage/);
  assert.equal(gen(['gen', '--project', ROOT, '--out', out]).status, 2);
  assert.equal(existsSync(out), false);
});

test('vectors --kind npm writes the golden tests/vectors.mjs to the --out file', () => {
  const file = path.join(tempDir(), 'tests', 'vectors.mjs');
  assert.deepEqual(gen(['vectors', '--project', ROOT, '--kind', 'npm', '--out', file]), { status: 0, stdout: '[status-gen] vectors: ok\n', stderr: '' });
  assert.equal(readFileSync(file, 'utf8'), golden('vectors.mjs'));
});

test('vectors --kind npm refuses to overwrite a file without the header', () => {
  const file = path.join(tempDir(), 'vectors.mjs');
  writeFileSync(file, 'export const vectors = [];\n');
  const result = gen(['vectors', '--project', ROOT, '--kind', 'npm', '--out', file]);
  assert.equal(result.status, 1);
  assert.match(result.stderr, /^\[status-gen\] E_NOT_GENERATED - vectors\.mjs: /m);
  assert.equal(readFileSync(file, 'utf8'), 'export const vectors = [];\n');
});

test('vectors with an unknown kind is a usage error', () => {
  assert.equal(gen(['vectors', '--project', ROOT, '--kind', 'ruby', '--out', path.join(tempDir(), 'v.mjs')]).status, 2);
});
